    def __init__(self): self.s=socket.create_connection(('127.0.0.1',6391)); self.b=b''
    def send(self,*a): self.s.sendall(enc(*a))
    def read(self):
        def line():
            while b'\r\n' not in self.b:
                d=self.s.recv(65536)
                if not d: raise EOFError
                self.b+=d
            x,self.b=self.b.split(b'\r\n',1); return x
        x=line(); t=x[:1]; x=x[1:]
        if t in (b'+',b'-'): return t,x
        if t==b':': return t,int(x)
        if t==b'$':
            n=int(x)
            if n<0:return t,None
            while len(self.b)<n+2:
                d=self.s.recv(65536)
                if not d:raise EOFError
                self.b+=d
            v,self.b=self.b[:n],self.b[n+2:]
            return t,v
        raise AssertionError(x)
    def cmd(self,*a):self.send(*a);return self.read()
